/* Selected B: four guardian gates. Earlier A/B/C remain in the immutable v17 snapshot. */
const RealmMapStudy=(()=>{
    const titles={B:'Guardian Gates · selected B'};
    let band=null,lastModal=null;
    const key=()=>'B';
    const enabled=()=>RealmProgression.enabled();
    const model=()=>RealmProgression.inspect();
    const pair=()=>({tier:state.modal.journeyTier??model().tier,realm:state.modal.journeyRealm??model().realm});
    const bounds=i=>({from:i?MageRealms.journey.bossNodes[i-1]+1:1,to:MageRealms.journey.bossNodes[i]});
    const currentBand=s=>Math.max(0,MageRealms.journey.bossNodes.findIndex(n=>n>=s.node));
    function bossName(r,i){return i===3?MageRealms.routes[r].boss.guardian:r===0?['The Ember Watcher','The Cinder Warden','The Ashen Knight'][i]:realms[r]+' '+['Watcher','Warden','Knight'][i];}
    const inspect=()=>({variant:key(),band,journey:model()});
    function basis(){const d=document.createElement('div');d.innerHTML=RealmProgression.view();return d;}
    function nodeHTML(base,n,extra='',style=''){const el=base.querySelector('[data-journey-node="'+n+'"]');const node=el.cloneNode(true);node.classList.add(...extra.split(' ').filter(Boolean));if(style)node.setAttribute('style',style);return node.outerHTML;}
    function gates(base,s,tier,realm){const cleared=MageRealms.journey.cleared(s,tier,realm),same=tier===s.tier&&realm===s.realm;return `<div class="map-gates map-study-canvas">${MageRealms.journey.bossNodes.map((boss,i)=>{const b=bounds(i),active=same&&s.node>=b.from&&s.node<=b.to,done=cleared>=boss,ready=cleared===boss-1&&MageRealms.journey.canVisit(s,tier,realm);return `<button class="map-band-card ${active?'current':''} ${done?'complete':''} ${ready?'ready':''}" data-map-band="${i}" aria-label="${bossName(realm,i)}, nodes ${b.from} through ${b.to}${active?', farming here':done?', cleared':''}. Explore this path"><span class="gate-portrait">${sprite(EncounterArt.boss(realm,boss))}${done?'<i>✓</i>':''}</span><span class="gate-copy"><strong>${bossName(realm,i).replace(/^The /,'')}</strong><span class="band-track" aria-hidden="true">${Array.from({length:boss-b.from+1},(_,j)=>`<i class="${b.from+j<=cleared?'done':''} ${same&&b.from+j===s.node?'here':''} ${j===boss-b.from?'boss-pip':''}"></i>`).join('')}</span><small>${b.from}–${b.to} <span>${ready?'Boss ready':active?'Farming here':done?'Cleared':'Explore'}</span></small></span><span class="gate-count">${done?'✓':Math.max(0,Math.min(boss-b.from+1,cleared-b.from+1))+' / '+(boss-b.from+1)}<b aria-hidden="true">›</b></span></button>`;}).join('')}</div>`;}
    function focus(base,s,tier,realm){const b=bounds(band);return `<div class="map-focus map-study-canvas focus-${key()}"><div class="focus-heading"><button class="text-button" data-map-overview aria-label="Back to realm overview">←</button><div><strong>${bossName(realm,band)}</strong><span>Nodes ${b.from}–${b.to}</span></div></div><div class="focus-path" role="group" aria-label="Nodes ${b.from} through ${b.to}">${Array.from({length:b.to-b.from+1},(_,i)=>nodeHTML(base,b.from+i,'focus-marker')).join('')}</div><div class="focus-goal">${sprite(EncounterArt.boss(realm,b.to))}<span>Boss · ${b.to}</span></div></div>`;}
    function view(){if(state.modal!==lastModal){band=null;lastModal=state.modal;}const s=model(),{tier,realm}=pair(),base=basis(),heading=base.querySelector('.tier-map-heading').outerHTML,tabs=base.querySelector('.tier-realms').outerHTML,footer=base.querySelector('.journey-footer').outerHTML;if(tier===s.tier&&realm===s.realm)base.querySelector('.journey-position strong').textContent+=' · Node '+s.node;const content=band!==null?focus(base,s,tier,realm):gates(base,s,tier,realm);const legend=band!==null?base.querySelector('.journey-map-key').outerHTML:`<div class="journey-map-key"><span>25 nodes</span><span>${sprite('golem')} 4 bosses</span><span>Choose a gate</span></div>`;return `<div class="tier-journey realm-map-study map-${key()}" data-map-layout="${key()}">${heading}${tabs}${base.querySelector('.journey-position').outerHTML}${content}${legend}${footer}</div>`;}
    function refreshAtlas(){const root=phone.querySelector('.realm-map-study');if(!root)return;const next=document.createElement('div');next.innerHTML=view();for(const old of root.querySelectorAll('button')){const attr=['data-journey-node','data-map-current','data-map-band','data-map-overview','data-journey-primary','data-journey-realm','data-journey-tier'].find(k=>old.hasAttribute(k));if(!attr)continue;const fresh=next.querySelector('['+attr+'="'+old.getAttribute(attr)+'"]');if(!fresh)continue;old.className=fresh.className;old.disabled=fresh.disabled;old.innerHTML=fresh.innerHTML;for(const k of ['aria-current','aria-label','aria-pressed', 'style']){if(fresh.hasAttribute(k))old.setAttribute(k,fresh.getAttribute(k));else old.removeAttribute(k);}}
        for(const selector of ['.map-geometry','.journey-position']){const old=root.querySelector(selector),fresh=next.querySelector(selector);if(old&&fresh)old.innerHTML=fresh.innerHTML;}
        const old=root.querySelector('.journey-footer>button'),fresh=next.querySelector('.journey-footer>button');if(old&&fresh){old.innerHTML=fresh.innerHTML;old.disabled=fresh.disabled;old.className=fresh.className;if(fresh.dataset.journeyPrimary)old.dataset.journeyPrimary=fresh.dataset.journeyPrimary;}
    }
    function change(delta){RealmProgression.change(delta);}
    function handle(el){if(el.dataset.journeyScenario){band=null;RealmProgression.scenario(el.dataset.journeyScenario);openModal({type:'map'});return true;}if(el.dataset.mapBand!==undefined){band=Number(el.dataset.mapBand);render(true);return true;}if(el.hasAttribute('data-map-overview')){band=null;render(true);return true;}if(el.dataset.journeyRealm!==undefined||el.dataset.journeyTier!==undefined||el.dataset.journeyScenario)band=null;return false;}
    function start(){if(!enabled())return;document.body.classList.add('map-comparison');}

    return {enabled,inspect,view,refreshAtlas,change,handle,label:()=>titles[key()],start};
})();
